select n.id as id from notes n  left join (select t.note_id, t.metric from unnest(:rankCopiesIds::uuid[], :rankCopiesValues::bigint[]) as t(note_id, metric)) rank_copies on rank_copies.note_id = n.id  left join (select t.note_id, t.metric from unnest(:rankLikesIds::uuid[], :rankLikesValues::bigint[]) as t(note_id, metric)) rank_likes on rank_likes.note_id = n.id  left join (select t.note_id, t.metric from unnest(:rankViewsIds::uuid[], :rankViewsValues::bigint[]) as t(note_id, metric)) rank_views on rank_views.note_id = n.id  where n.visibility = 'PUBLIC' and n.id = any(:rankTagIds::uuid[]) and (coalesce(rank_copies.metric, 0) >= 3 or coalesce(rank_views.metric, 0) >= 20)  order by coalesce(rank_copies.metric, 0) desc, coalesce(rank_views.metric, 0) desc, coalesce(rank_likes.metric, 0) desc, n.created_at desc, n.id asc limit :rankLimit offset :rankOffset